"""First independent, context-driven animated scene prototype.

Creates a self-contained HTML/SVG environment (not a static background with
floating decorative shapes). This is a proof-of-concept scene, not photorealism.
"""
from __future__ import annotations
import html
from typing import Any


def _safe(value: Any) -> str:
    return html.escape(str(value or ""), quote=True)


def build_scene_html(scene: dict[str, Any], duration_seconds: float = 8.0) -> str:
    intent = str(scene.get("intent", "explanation"))
    spoken = _safe(scene.get("spoken_text", ""))
    label = _safe(scene.get("intent_label", "مشهد توضيحي"))
    duration = max(4.0, min(float(duration_seconds), 20.0))

    # The scene composition changes by intent; motion is attached to scene objects.
    if intent == "time":
        objects = '''
        <g id="window"><rect x="85" y="110" width="300" height="250" rx="12" fill="#d9e8ec" stroke="#38576a" stroke-width="12"/><path d="M235 116V354M91 235H379" stroke="#7194a2" stroke-width="8"/><path d="M110 325L190 245L260 295L360 180" fill="none" stroke="#93b9b0" stroke-width="12" opacity=".75"/></g>
        <g id="clock" class="clock"><circle cx="820" cy="190" r="86" fill="#fff8e8" stroke="#294451" stroke-width="16"/><circle cx="820" cy="190" r="5" fill="#294451"/><path d="M820 190V130M820 190L860 210" stroke="#294451" stroke-width="12" stroke-linecap="round"/><path d="M820 117V130M893 190H880M820 263V250M747 190H760" stroke="#718994" stroke-width="6" stroke-linecap="round"/></g>
        <g id="desk"><path d="M80 660H1000L930 715H140Z" fill="#956747"/><path d="M155 710L125 1020M915 710L950 1020" stroke="#5b4538" stroke-width="26" stroke-linecap="round"/><rect x="330" y="470" width="360" height="205" rx="18" fill="#253743"/><rect x="350" y="490" width="320" height="160" rx="8" fill="#b7d4d2"/><rect x="380" y="520" width="165" height="12" rx="6" fill="#4c7e7a"/><rect x="380" y="550" width="230" height="10" rx="5" fill="#769f9a"/><rect x="380" y="576" width="190" height="10" rx="5" fill="#769f9a"/><path d="M290 680H730L680 712H340Z" fill="#4b5e68"/><g class="typing"><path d="M390 700L430 716M450 700L490 716M510 700L550 716M570 700L610 716" stroke="#e8f0ec" stroke-width="6" stroke-linecap="round"/></g></g>
        <g id="person"><ellipse cx="520" cy="435" rx="70" ry="82" fill="#c98e69"/><path d="M450 420Q440 340 520 340Q605 350 590 426L570 395L470 400Z" fill="#29343a"/><path d="M400 510Q520 455 640 510L690 660H350Z" fill="#477d77"/><path d="M440 535L380 635M600 535L660 625" stroke="#c98e69" stroke-width="30" stroke-linecap="round"/><circle cx="495" cy="430" r="6" fill="#29343a"/><circle cx="548" cy="430" r="6" fill="#29343a"/><path d="M500 465Q520 477 540 463" stroke="#8d5547" stroke-width="5" fill="none" stroke-linecap="round"/></g>
        <g id="coffee"><path d="M760 620H830L818 680H772Z" fill="#f4e9d4"/><path d="M830 632Q875 628 855 660H822" fill="none" stroke="#f4e9d4" stroke-width="10"/><path class="steam" d="M780 610Q765 590 785 575M805 610Q825 588 805 568" fill="none" stroke="#fff8e8" stroke-width="5" stroke-linecap="round"/></g>
        '''
    elif intent == "social":
        objects = '''
        <g id="room-window"><rect x="90" y="120" width="330" height="270" rx="14" fill="#d7e8e7" stroke="#39545a" stroke-width="12"/><path d="M255 126V384M96 255H414" stroke="#6d9997" stroke-width="8"/><circle cx="330" cy="180" r="38" fill="#f4c77a"/></g>
        <g id="desk"><path d="M70 700H1010L945 750H130Z" fill="#9b7558"/><path d="M160 745L135 1030M910 745L940 1030" stroke="#644c3c" stroke-width="25" stroke-linecap="round"/><g id="phone" class="phone"><rect x="650" y="400" width="205" height="360" rx="30" fill="#1f2d37" stroke="#0e171d" stroke-width="8"/><rect x="666" y="430" width="173" height="300" rx="18" fill="#f7faf8"/><rect x="680" y="448" width="145" height="88" rx="10" fill="#dcece5"/><circle cx="710" cy="476" r="15" fill="#4d887b"/><rect x="735" y="464" width="76" height="9" rx="4" fill="#668e84"/><rect x="735" y="482" width="60" height="7" rx="3" fill="#a2bcb4"/><rect x="680" y="550" width="145" height="72" rx="10" fill="#f0d8bd"/><path d="M695 605L725 575L750 594L785 560L810 600" stroke="#ba8760" stroke-width="8" fill="none"/><rect x="680" y="635" width="92" height="9" rx="4" fill="#77958c"/><rect x="680" y="654" width="125" height="7" rx="3" fill="#c1d1cb"/><circle cx="752" cy="744" r="5" fill="#9fb2ad"/></g>
        <g id="creator"><ellipse cx="420" cy="440" rx="72" ry="82" fill="#c98e69"/><path d="M350 425Q340 345 420 345Q500 355 490 430L470 395L370 400Z" fill="#29343a"/><path d="M300 520Q420 460 540 520L585 690H255Z" fill="#6b879e"/><path d="M340 545L460 625" stroke="#c98e69" stroke-width="28" stroke-linecap="round"/><path d="M465 625L625 600" stroke="#c98e69" stroke-width="24" stroke-linecap="round"/><circle cx="397" cy="438" r="6" fill="#29343a"/><circle cx="445" cy="438" r="6" fill="#29343a"/><path d="M400 468Q420 478 440 466" stroke="#8d5547" stroke-width="5" fill="none"/></g>
        <g id="plant"><path d="M180 700V550" stroke="#52775f" stroke-width="12"/><path d="M180 620Q95 590 120 535Q175 550 180 620M180 585Q250 535 260 485Q195 490 180 585M180 555Q145 490 165 450Q215 495 180 555" fill="#6b9a79"/><path d="M140 700H220L205 760H155Z" fill="#c58b69"/></g>
        '''
    elif intent == "editing":
        objects = '''
        <g id="editor-bg"><rect x="55" y="105" width="890" height="570" rx="24" fill="#111a20"/><rect x="80" y="135" width="520" height="330" rx="12" fill="#25353c"/><rect x="98" y="153" width="484" height="294" rx="8" fill="#f1f3ef"/><rect x="120" y="175" width="440" height="250" rx="5" fill="#dce7e3"/><circle cx="335" cy="286" r="86" fill="#b9d6ce"/><path d="M280 340L330 245L390 340Z" fill="#477e73"/><rect x="625" y="145" width="290" height="310" rx="12" fill="#202d34"/><rect x="650" y="175" width="240" height="16" rx="8" fill="#7ba99d"/><rect x="650" y="208" width="190" height="10" rx="5" fill="#536b70"/><rect x="650" y="232" width="220" height="10" rx="5" fill="#536b70"/><rect x="650" y="256" width="160" height="10" rx="5" fill="#536b70"/></g>
        <g id="timeline"><rect x="80" y="490" width="840" height="145" rx="10" fill="#26363e"/><path d="M105 535H895M105 580H895" stroke="#53656b" stroke-width="3"/><g class="clip-a"><rect x="110" y="505" width="190" height="25" rx="5" fill="#d1a35e"/><rect x="310" y="505" width="160" height="25" rx="5" fill="#6ca79a"/><rect x="480" y="505" width="230" height="25" rx="5" fill="#7794b6"/><rect x="720" y="505" width="160" height="25" rx="5" fill="#d1a35e"/></g><rect x="110" y="548" width="280" height="25" rx="5" fill="#7ba99d"/><rect x="400" y="548" width="205" height="25" rx="5" fill="#bf7e77"/><rect x="615" y="548" width="265" height="25" rx="5" fill="#7ba99d"/><path class="playhead" d="M360 482V625" stroke="#f6f7f2" stroke-width="5"/><path d="M350 482L370 482L360 495Z" fill="#f6f7f2"/></g>
        <g id="play-controls"><circle cx="120" cy="445" r="18" fill="#d8e7e1"/><path d="M114 434L114 456L132 445Z" fill="#244b45"/><rect x="160" y="438" width="250" height="12" rx="6" fill="#c5d4ce"/></g>
        '''
    elif intent == "ai":
        objects = '''
        <g id="ai-editorial"><rect x="65" y="110" width="890" height="820" rx="26" fill="#11191d"/><circle cx="760" cy="300" r="220" fill="#1c4c49"/><circle cx="760" cy="300" r="150" fill="#28766a"/><path d="M620 425Q640 235 770 220Q895 235 915 425Z" fill="#d6e4df"/><ellipse cx="770" cy="310" rx="90" ry="112" fill="#c5d6cf"/><path d="M685 285Q690 190 775 195Q860 200 855 285L830 255L710 260Z" fill="#26343a"/><path d="M630 450Q770 390 910 450L950 650H590Z" fill="#e4eee8"/><rect x="100" y="190" width="370" height="95" rx="8" fill="#f3f4ed"/><rect x="100" y="305" width="290" height="18" rx="9" fill="#829d95"/><rect x="100" y="342" width="330" height="18" rx="9" fill="#829d95"/><rect x="100" y="379" width="240" height="18" rx="9" fill="#829d95"/><circle class="ai-orbit" cx="770" cy="310" r="245" fill="none" stroke="#d4a85e" stroke-width="4" stroke-dasharray="18 22"/></g>
        '''
    elif intent == "product":
        objects = '''
        <g id="shelf"><rect x="90" y="170" width="900" height="28" rx="8" fill="#6f5545"/><rect x="120" y="198" width="18" height="230" fill="#8c6b54"/><rect x="940" y="198" width="18" height="230" fill="#8c6b54"/><rect x="90" y="440" width="900" height="28" rx="8" fill="#6f5545"/></g>
        <g id="bottle" class="product-focus"><ellipse cx="530" cy="770" rx="210" ry="35" fill="#1b2b30" opacity=".18"/><path d="M465 420H595V485L630 530V740Q630 770 600 770H460Q430 770 430 740V530L465 485Z" fill="#d8c6a4" stroke="#6b5540" stroke-width="10"/><rect x="475" y="350" width="110" height="75" rx="12" fill="#3b4644"/><rect x="490" y="300" width="80" height="55" rx="8" fill="#d9b56c"/><rect x="455" y="575" width="150" height="100" rx="8" fill="#f6eee0"/><text x="530" y="615" text-anchor="middle" font-size="25" fill="#5a4437" font-family="sans-serif" font-weight="700">PARFUM</text><text x="530" y="650" text-anchor="middle" font-size="16" fill="#81654f" font-family="sans-serif">EAU DE PARFUM</text></g>
        <g id="product-light"><path d="M180 120L380 120L480 450L250 450Z" fill="#f3d69b" opacity=".25"/><path d="M900 120L700 120L600 450L830 450Z" fill="#f3d69b" opacity=".2"/></g>
        <g id="hands"><path d="M300 700Q340 655 385 690L445 735Q465 760 440 778L360 750Z" fill="#c98e69"/><path d="M760 700Q720 655 675 690L615 735Q595 760 620 778L700 750Z" fill="#c98e69"/></g>
        '''
    else:
        objects = '''
        <g id="studio-window"><rect x="100" y="100" width="310" height="290" rx="14" fill="#dce9e8" stroke="#3e5960" stroke-width="12"/><path d="M255 106V384M106 245H404" stroke="#789b9a" stroke-width="8"/><circle cx="330" cy="170" r="36" fill="#f4c77a"/></g>
        <g id="workbench"><path d="M70 700H1010L945 750H135Z" fill="#997354"/><path d="M155 745L130 1030M920 745L945 1030" stroke="#624b3a" stroke-width="25" stroke-linecap="round"/><rect x="360" y="430" width="360" height="235" rx="18" fill="#273944"/><rect x="380" y="450" width="320" height="185" rx="8" fill="#c5ddd5"/><rect x="410" y="485" width="190" height="12" rx="6" fill="#4e8377"/><rect x="410" y="515" width="250" height="9" rx="4" fill="#85aaa0"/><rect x="410" y="540" width="210" height="9" rx="4" fill="#85aaa0"/><path d="M315 675H765L720 708H360Z" fill="#4b5f69"/></g>
        <g id="person"><ellipse cx="520" cy="380" rx="75" ry="86" fill="#c98e69"/><path d="M445 365Q438 280 520 285Q605 290 600 365L575 330L470 335Z" fill="#29343a"/><path d="M385 475Q520 415 655 475L700 700H340Z" fill="#477d77"/><path d="M430 520L380 625M610 520L660 625" stroke="#c98e69" stroke-width="28" stroke-linecap="round"/><circle cx="495" cy="380" r="6" fill="#29343a"/><circle cx="548" cy="380" r="6" fill="#29343a"/></g>
        <g id="plant"><path d="M180 700V550" stroke="#52775f" stroke-width="12"/><path d="M180 620Q95 590 120 535Q175 550 180 620M180 585Q250 535 260 485Q195 490 180 585" fill="#6b9a79"/><path d="M140 700H220L205 760H155Z" fill="#c58b69"/></g>
        '''

    title = {"time": "الوقت يضغط عليك", "social": "أنشئ وانشر محتواك", "product": "تفاصيل المنتج", "editing": "المونتاج يتحول إلى فعل مرئي", "ai": "الذكاء الاصطناعي في سياقه", "explanation": "الفكرة تتحول إلى مشهد"}.get(intent, "الفكرة تتحول إلى مشهد")
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{label}</title>
<style>
*{{box-sizing:border-box}}body{{margin:0;background:#e9eeeb;font-family:Arial,'Noto Sans Arabic',sans-serif;color:#182b31}}.frame{{width:min(100vw,540px);aspect-ratio:9/16;margin:0 auto;position:relative;overflow:hidden;background:#dfe8e4;box-shadow:0 18px 60px #182b3120}}svg{{width:100%;height:100%;display:block}}.caption{{position:absolute;left:6%;right:6%;bottom:7%;padding:18px 20px;border-radius:18px;background:#f8faf6ee;border:1px solid #bacbc4;box-shadow:0 8px 28px #182b3120;font-size:clamp(15px,3.1vw,22px);font-weight:700;line-height:1.65;text-align:center}}.tag{{position:absolute;top:5%;right:6%;background:#214e49;color:#fff;padding:8px 13px;border-radius:99px;font-size:12px;letter-spacing:.2px}}.progress{{position:absolute;bottom:3.5%;left:6%;right:6%;height:4px;background:#bdcbc5;border-radius:9px;overflow:hidden}}.progress:after{{content:'';display:block;height:100%;background:#d29a50;transform-origin:right;animation:progress {duration}s linear infinite}}#scene-art{{animation:camera {duration}s ease-in-out infinite alternate;transform-origin:center}}.clock{{transform-origin:820px 190px;animation:tick 4s linear infinite}}.typing{{animation:typing .6s ease-in-out infinite alternate}}.steam{{animation:steam 2s ease-in-out infinite alternate}}.phone{{animation:phone .7s ease-in-out infinite alternate;transform-origin:750px 580px}}.product-focus{{animation:product 5s ease-in-out infinite alternate;transform-origin:530px 600px}}.playhead{{animation:playhead {duration}s linear infinite}}.ai-orbit{{transform-origin:770px 310px;animation:tick 18s linear infinite}}@keyframes camera{{from{{transform:translate(0,0) scale(1)}}to{{transform:translate(-12px,-8px) scale(1.035)}}}}@keyframes tick{{to{{transform:rotate(360deg)}}}}@keyframes typing{{from{{opacity:.35;transform:translateY(0)}}to{{opacity:1;transform:translateY(-4px)}}}}@keyframes steam{{from{{opacity:.25;transform:translateY(4px)}}to{{opacity:.8;transform:translateY(-8px)}}}}@keyframes phone{{from{{transform:rotate(-1deg)}}to{{transform:rotate(1deg)}}}}@keyframes product{{from{{transform:translateY(5px) scale(1)}}to{{transform:translateY(-6px) scale(1.025)}}}}@keyframes playhead{{from{{transform:translateX(0)}}to{{transform:translateX(480px)}}}}@keyframes progress{{from{{transform:scaleX(0)}}to{{transform:scaleX(1)}}}}@media(prefers-reduced-motion:reduce){{*,*:before,*:after{{animation:none!important}}}}
</style></head><body><div class="frame"><svg viewBox="0 0 1080 1920" role="img" aria-label="مشهد سياقي متحرك"><defs><linearGradient id="wall" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f4f0e5"/><stop offset="1" stop-color="#d6e1da"/></linearGradient><linearGradient id="floor" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b8a18a"/><stop offset="1" stop-color="#8f765f"/></linearGradient><radialGradient id="light"><stop stop-color="#fff5d7" stop-opacity=".8"/><stop offset="1" stop-color="#fff5d7" stop-opacity="0"/></radialGradient></defs><g id="scene-art"><rect width="1080" height="1920" fill="url(#wall)"/><circle cx="300" cy="250" r="390" fill="url(#light)"/><path d="M0 1120L1080 1040V1920H0Z" fill="url(#floor)"/><path d="M0 1150L1080 1070M0 1350L1080 1280M0 1570L1080 1490M0 1770L1080 1700" stroke="#765e4c" stroke-width="5" opacity=".22"/>{objects}</g></svg><div class="tag">{label}</div><div class="caption">{spoken}</div><div class="progress"></div></div></body></html>'''
